const raw = $input.first().json;
const jobs = Array.isArray(raw) ? raw.slice(1) : [];
return jobs
  .filter(j => j && j.position)
  .map(job => ({
    json: {
      job_id: `remoteok-${job.id || job.slug}`,
      job_title: job.position || '',
      company: job.company || '',
      job_url: job.url || `https://remoteok.com/remote-jobs/${job.id}`,
      source: 'Remote OK',
      location_text: job.location || 'Worldwide',
      salary: job.salary_min ? `$${Math.round(job.salary_min/1000)}k-$${Math.round((job.salary_max||job.salary_min)/1000)}k/yr` : '',
      description: (job.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
      posted_date: job.date || new Date().toISOString(),
      tags: (job.tags || []).join(', ')
    }
  }));

const data = $input.first().json;
const jobs = data.jobs || [];
return jobs.map(job => ({
  json: {
    job_id: `remotive-${job.id}`,
    job_title: job.title || '',
    company: job.company_name || '',
    job_url: job.url || '',
    source: 'Remotive',
    location_text: job.candidate_required_location || 'Worldwide',
    salary: job.salary || '',
    description: (job.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
    posted_date: job.publication_date || new Date().toISOString(),
    tags: (job.tags || []).join(', ')
  }
}));

return $input.all().map(item => {
  const d = item.json;
  const titleParts = (d.title || '').split(':');
  const company = titleParts.length > 1 ? titleParts[0].trim() : 'Unknown';
  const jobTitle = titleParts.length > 1 ? titleParts.slice(1).join(':').trim() : (d.title || '');
  return {
    json: {
      job_id: `wwr-${Buffer.from(d.link || d.guid || Math.random().toString()).toString('base64').substring(0, 20)}`,
      job_title: jobTitle,
      company,
      job_url: d.link || '',
      source: 'We Work Remotely',
      location_text: 'Remote',
      salary: '',
      description: (d.content || d.summary || d.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
      posted_date: d.pubDate || d.isoDate || new Date().toISOString(),
      tags: d.categories ? (Array.isArray(d.categories) ? d.categories.join(', ') : d.categories) : ''
    }
  };
});

const data = $input.first().json;
const jobs = data.jobs || (Array.isArray(data) ? data : []);
return jobs.map(job => {
  const salaryMin = job.annualSalaryMin || job.salaryMin || 0;
  const salaryMax = job.annualSalaryMax || job.salaryMax || 0;
  return {
    json: {
      job_id: `himalayas-${job.id || job.slug || Math.random().toString(36).substr(2,9)}`,
      job_title: job.title || '',
      company: (job.company && job.company.name) ? job.company.name : (job.companyName || ''),
      job_url: job.applicationLink || `https://himalayas.app/jobs/${job.slug || job.id}`,
      source: 'Himalayas',
      location_text: (job.locationRestrictions || []).join(', ') || 'Worldwide',
      salary: salaryMin > 0 ? `$${Math.round(salaryMin/1000)}k-$${Math.round(salaryMax/1000)}k/yr` : '',
      description: (job.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
      posted_date: job.createdAt || job.publishedAt || new Date().toISOString(),
      tags: (job.skills || job.tags || []).join(', ')
    }
  };
});

return $input.all().map(item => {
  const d = item.json;
  return {
    json: {
      job_id: `dynamite-${Buffer.from(d.link || d.guid || Math.random().toString()).toString('base64').substring(0, 20)}`,
