const data = $input.first().json;
const jobs = Array.isArray(data) ? data : (data.jobs || []);
return jobs.map(job => ({
  json: {
    job_id: `yc-${job.id || Math.random().toString(36).substr(2,9)}`,
    job_title: job.title || job.role || '',
    company: (job.company && job.company.name) ? job.company.name : (job.company_name || ''),
    job_url: job.url || job.job_url || `https://www.workatastartup.com/jobs/${job.id}`,
    source: 'YC Work at a Startup',
    location_text: job.location || 'Remote',
    salary: job.salary || '',
    description: (job.description || job.body || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
    posted_date: job.created_at || job.posted_at || new Date().toISOString(),
    tags: (job.skills || job.tags || []).join(', ')
  }
}));

// Wellfound returns HTML or JSON depending on setup
// Adjust this parser based on your scraping configuration
const data = $input.first().json;
const jobs = Array.isArray(data) ? data : (data.jobs || data.startupRoles || []);
if (jobs.length === 0) return [];
return jobs.map(job => ({
  json: {
    job_id: `wellfound-${job.id || Math.random().toString(36).substr(2,9)}`,
    job_title: job.title || job.role || '',
    company: (job.startup && job.startup.name) ? job.startup.name : (job.company || ''),
    job_url: job.url || `https://wellfound.com/jobs/${job.id}`,
    source: 'Wellfound',
    location_text: job.locationNames || job.location || 'Remote',
    salary: job.salary || '',
    description: (job.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
    posted_date: job.created_at || new Date().toISOString(),
    tags: (job.tags || []).join(', ')
  }
}));

const items = $input.all();
const newJobs = items.filter(i => i.json._type === 'new');
const existingJobs = items.filter(i => i.json._type === 'existing');

const existingUrls = new Set(existingJobs.map(j => j.json.job_url).filter(Boolean));
const existingKeys = new Set(existingJobs.map(j => j.json._dedup_key).filter(k => k && k !== '|||'));

const seenUrls = new Set(existingUrls);
const seenKeys = new Set(existingKeys);
const unique = [];

for (const item of newJobs) {
  const url = (item.json.job_url || '').trim();
  const key = `${(item.json.company || '').toLowerCase()}|||${(item.json.job_title || '').toLowerCase()}`;
  if (!url) continue;
  if (seenUrls.has(url)) continue;
  if (key !== '|||' && seenKeys.has(key)) continue;
  seenUrls.add(url);
  seenKeys.add(key);
  const { _type, ...jobData } = item.json;
  unique.push({ json: jobData });
}

return unique;

const REJECT = [
  /\busa?[\s-]only\b/i, /\bunited\s+states\s+only\b/i,
  /\bcanada[\s-]only\b/i, /\buk[\s-]only\b/i, /\bunited\s+kingdom\s+only\b/i,
  /\beu[\s-]only\b/i, /\beurope[\s-]only\b/i, /\beuropean\s+union\s+only\b/i,
  /\baustralia[\s-]only\b/i, /\baus[\s-]only\b/i,
  /\bmust\s+be\s+(based|located|residing?)\s+in\b/i,
  /\bmust\s+live\s+in\b/i,
  /\bmust\s+(be\s+)?authorized\s+to\s+work\s+in\b/i,
  /\blocal\s+work\s+permit\s+required\b/i,
  /\b(must\s+)?reside\s+in\b/i,
  /\bwork\s+authorization\s+(in|for)\s+(the\s+)?(us|uk|eu|canada|australia)\b/i,
  /\bauthorized\s+to\s+work\s+in\s+the\s+(us|uk)\b/i,
  /\bUS\s+work\s+authorization\b/,
  /\bhybrid\b/i, /\bon[\s-]?site\b/i, /\bin[\s-]?office\b/i,
  /\boffice[\s-]?required\b/i, /\bremote[\s-]?within\b/i,
  /\bfixed\s+(us|est|pst|cet|gmt|uk)\s+hours\b/i,
  /\bphysically\s+(present|based)\s+in\b/i
];
const LOC_ONLY = [
  /^(united\s+states|usa|us)$/i, /^(united\s+kingdom|uk|gb)$/i,
  /^(canada)$/i, /^(europe|european\s+union|eu)$/i, /^(australia)$/i
];

return $input.all().filter(item => {
  const text = `${item.json.description || ''} ${item.json.location_text || ''}`.toLowerCase();
  const loc = (item.json.location_text || '').trim();
  for (const p of REJECT) if (p.test(text)) return false;
  for (const p of LOC_ONLY) if (p.test(loc)) return false;
  return true;
});

const aiItem = $input.first();
const rawContent = aiItem.json?.choices?.[0]?.message?.content ||
  aiItem.json?.message?.content || '{}';

let ai = {};
try {
  const match = rawContent.match(/\{[\s\S]*\}/);
  if (match) ai = JSON.parse(match[0]);
} catch(e) {
  ai = { taiwan_eligible: 'unclear', reason: 'Parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
}

// Get original job from the Write Raw Jobs node
const job = $('Write Raw Jobs').first().json;
const desc = ((job.description || '') + ' ' + (job.location_text || '') + ' ' + (job.tags || '')).toLowerCase();
const title = (job.job_title || '').toLowerCase();

// ASYNC LEVEL
const ASYNC_POS = ['async','asynchronous','flexible hours','flexible schedule','distributed team','remote-first','remote first','low meeting','time zone flexible','across time zones','no meetings','own schedule','your own hours','fully distributed'];
const ASYNC_NEG = ['strict 9-5','strict 9 to 5','fixed us hours','fixed est hours','fixed pst hours','fixed cet hours','must overlap','required overlap','daily standups required','daily live call','full business day overlap'];

let asyncLevel = 'low';
if (!ASYNC_NEG.some(k => desc.includes(k))) {
  const cnt = ASYNC_POS.filter(k => desc.includes(k)).length;
  asyncLevel = cnt >= 2 ? 'high' : cnt === 1 ? 'medium' : 'low';
}

// ROLE FIT
const ROLE_PRIMARY = ['data analyst','data scientist','business intelligence','bi analyst','marketing analyst','performance marketing','growth analyst','ai marketing','ai automation','ai workflow','martech analyst','analytics engineer','product analyst','revenue analyst','marketing data','machine learning'];
const ROLE_ADJ = ['analyst','scientist','marketing','growth','automation','intelligence','insights','reporting','metrics','dashboard','analytics'];

let roleCategory = 'other';
for (const r of ROLE_PRIMARY) {
  if (title.includes(r) || desc.includes(r)) { roleCategory = 'primary'; break; }
}
if (roleCategory === 'other') {
  for (const r of ROLE_ADJ) {
    if (title.includes(r)) { roleCategory = 'adjacent'; break; }
  }
}

// SCORING
let score = 0;
const breakdown = [];

// Taiwan eligibility (0-40)
const TW_POS = ['worldwide','work from anywhere','global remote','anywhere in the world','fully distributed','international contractors','open to all countries','deel','remote.com','oyster','eor','employer of record','b2b contract'];
const APAC_POS = ['apac','asia pacific','asia-pacific','southeast asia','east asia'];

if (ai.taiwan_eligible === 'yes' || TW_POS.some(t => desc.includes(t))) {
  score += 40; breakdown.push('Taiwan eligible +40');
} else if (APAC_POS.some(t => desc.includes(t))) {
  score += 30; breakdown.push('APAC eligible +30');
} else if (ai.taiwan_eligible === 'unclear' && ai.location_risk !== 'high') {
  score += 20; breakdown.push('Unclear eligibility +20');
} else {
  breakdown.push('Restricted +0');
}

// Async (0-25)
if (asyncLevel === 'high') { score += 25; breakdown.push('Async high +25'); }
else if (asyncLevel === 'medium') { score += 20; breakdown.push('Async medium +20'); }
else if (desc.includes('distributed')) { score += 15; breakdown.push('Distributed +15'); }
else if (desc.includes('remote-first') || desc.includes('remote first')) { score += 10; breakdown.push('Remote-first +10'); }

// Role (0-25)
if (roleCategory === 'primary') { score += 25; breakdown.push('Primary role +25'); }
else if (roleCategory === 'adjacent') { score += 15; breakdown.push('Adjacent role +15'); }

// Salary (0-25)
const salStr = job.salary || '';
let salPts = 0;
if (salStr.match(/\d/)) {
  const nums = salStr.match(/\d[\d,.]*/g) || [];
  const top = Math.max(...nums.map(n => parseFloat(n.replace(/,/g,''))));
  if (top > 0) {
    const isAnnual = top > 500 || /year|annual|\/yr/i.test(salStr);
    const monthly = isAnnual ? top / 12 : top;
    salPts = monthly >= 5000 ? 25 : monthly >= 3000 ? 15 : 10;
    score += salPts;
    breakdown.push(`Salary $${Math.round(monthly)}/mo +${salPts}`);
  }
}

// WHY GOOD FIT
const why = [];
if (ai.taiwan_eligible === 'yes') why.push('Confirmed Taiwan-eligible');
if (asyncLevel !== 'low') why.push(`${asyncLevel} async culture`);
if (roleCategory === 'primary') why.push('Strong data/AI/marketing match');
else if (roleCategory === 'adjacent') why.push('Adjacent to analytics skills');
if (job.salary) why.push(`Salary listed: ${job.salary}`);
if (/deel|remote\.com|oyster/i.test(desc)) why.push('EOR/contractor platform mentioned');
if (/bilingual|mandarin|chinese/i.test(desc)) why.push('Bilingual valued');

// DECISION
let decision;
if (ai.taiwan_eligible === 'no' || ai.location_risk === 'high') {
  decision = 'reject';
} else if (score >= 85) {
  decision = 'apply_now';
} else if (score >= 70) {
  decision = ai.taiwan_eligible === 'unclear' ? 'manual_check' : 'keep';
} else {
  decision = 'reject';
}

return [{
  json: {
    ...job,
    date_found: new Date().toISOString().split('T')[0],
    score,
    score_breakdown: breakdown.join(' | '),
    taiwan_eligible: ai.taiwan_eligible || 'unclear',
    taiwan_reason: ai.reason || '',
    location_risk: ai.location_risk || 'medium',
    timezone_risk: ai.timezone_risk || 'medium',
    contractor_possible: ai.contractor_possible || 'unclear',
    async_level: asyncLevel,
    role_category: roleCategory,
    why_good_fit: why.join('; '),
    decision,
    application_status: '',
    notes: ''
  }
}];

const allItems = $input.all();
const today = new Date().toISOString().split('T')[0];

// Filter to today's jobs
const items = allItems.filter(i => (i.json.date_found || '').startsWith(today));

if (items.length === 0) {
  return [{ json: {
    subject: `Daily Taiwan Jobs — ${today} — No new matches`,
    body: `<h2>Daily Taiwan Eligible Async Remote Jobs — ${today}</h2><p>No new matching jobs found today. All sources were checked.</p>`
  }}];
}

const sorted = items.sort((a,b) => (Number(b.json.score)||0) - (Number(a.json.score)||0));
const topJobs = sorted.filter(i => i.json.decision !== 'reject').slice(0, 10);
const manual = sorted.filter(i => i.json.decision === 'manual_check');
const rejected = sorted.filter(i => i.json.decision === 'reject');

const countReason = (keyword) => rejected.filter(i => (i.json.reason||'').toLowerCase().includes(keyword) || (i.json.taiwan_reason||'').toLowerCase().includes(keyword)).length;

let body = `<h2 style="color:#1a73e8;">Daily Taiwan Eligible Async Remote Jobs — ${today}</h2>`;
body += `<p><strong>✅ Matches: ${topJobs.length} | ⚠️ Manual review: ${manual.length} | ❌ Rejected: ${rejected.length}</strong></p><hr/>`;
body += `<h3>Top Jobs Today:</h3>`;

topJobs.forEach((item, i) => {
  const j = item.json;
  const badge = Number(j.score) >= 85 ? ' 🔥 HIGH PRIORITY' : Number(j.score) >= 80 ? ' ⭐ Strong match' : '';
  body += `
<div style="margin-bottom:24px;padding:16px;border-left:4px solid ${Number(j.score)>=85?'#e53935':'#43a047'};background:#f9f9f9;">
  <h4>${i+1}. ${j.job_title}${badge}</h4>
  <p><strong>Company:</strong> ${j.company}</p>
  <p><strong>Score:</strong> ${j.score}/100</p>
  <p><strong>Taiwan Eligible:</strong> ${j.taiwan_eligible} — ${j.taiwan_reason}</p>
  <p><strong>Async Level:</strong> ${j.async_level} | <strong>Timezone Risk:</strong> ${j.timezone_risk} | <strong>Location Risk:</strong> ${j.location_risk}</p>
  <p><strong>Salary:</strong> ${j.salary||'Not listed'}</p>
  <p><strong>Why It Fits Jerry:</strong> ${j.why_good_fit}</p>
  <p><a href="${j.job_url}" style="background:#1a73e8;color:white;padding:8px 16px;text-decoration:none;border-radius:4px;">Apply →</a></p>
</div>`;
});

if (manual.length > 0) {
  body += `<hr/><h3>⚠️ Manual Check Required (Taiwan eligibility unclear, score high):</h3><ul>`;
  manual.forEach(item => {
    const j = item.json;
    body += `<li><strong>${j.job_title}</strong> at ${j.company} — Score: ${j.score} — ${j.taiwan_reason} — <a href="${j.job_url}">View</a></li>`;
  });
  body += `</ul>`;
}

body += `<hr/><h3>Rejected Summary:</h3><ul>`;
body += `<li>❌ US/Canada restricted: ${countReason('us')+countReason('canada')}</li>`;
body += `<li>❌ EU/Europe restricted: ${countReason('eu')+countReason('europe')}</li>`;
body += `<li>❌ Hybrid/Onsite: ${countReason('hybrid')+countReason('onsite')}</li>`;
body += `<li>❌ Timezone incompatible: ${rejected.filter(i => i.json.timezone_risk === 'high').length}</li>`;
body += `<li>❌ Total rejected: ${rejected.length}</li></ul>`;
body += `<p style="color:#888;font-size:12px;">Powered by Daily Taiwan Eligible Async Remote Job Hunter — Jerry Dashboard</p>`;

return [{ json: {
  subject: `Daily Taiwan Jobs — ${today} — ${topJobs.length} matches, ${manual.length} to review`,
  body
}}];
